def solution(input_str):
    import sys
    from io import StringIO

    lines = input_str.strip().split('\n')
    t = int(lines[0])
    idx = 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for _ in range(n):
            row = list(map(int, lines[idx].split()))
            idx += 1
            matrix.append(row)

        # Count non-zero elements
        non_zero_count = 0
        for r in range(n):
            for c in range(m):
                if matrix[r][c] > 0:
                    non_zero_count += 1

        # If non_zero_count is odd, Ashish wins, otherwise Jeel wins
        # This is similar to Nim where each non-zero cell is essentially a "pile"
        if non_zero_count % 2 == 1:
            results.append("Ashish")
        else:
            results.append("Jeel")

    return '\n'.join(results)

