MOD = 1_000_000_000

def mat_mul(a, b):
    c = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            for k in range(2):
                c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % MOD
    return c

def mat_pow(a, n):
    result = [[1, 0], [0, 1]]
    base = [row[:] for row in a]
    while n > 0:
        if n & 1:
            result = mat_mul(result, base)
        base = mat_mul(base, base)
        n >>= 1
    return result

def fib_matrix(k):
    # Fib: [F(n), F(n-1)]^T = [ [1,1],[1,0] ]^k * [F(1),F(0)]^T = M^k * [1,0]
    # We use matrix for transformation
    if k == 0:
        return [1, 0]  # (f0, f0')
    M = [[1, 1], [1, 0]]
    result = mat_pow(M, k)
    return [result[0][0], result[0][1]]

class Node:
    __slots__ = 'val_sum', 'add_lazy', 'fib_nodes'

    def __init__(self, n):
        self.val_sum = 0       # actual sum of a[i] with base fib weights
        self.add_lazy = 0      # range add lazy value for current range
        self.lbases = [0] * (n + 2)  # fib weight accumulations

    def merge(self, left, right):
        self.val_sum = (left.val_sum + right.val_sum) % MOD
        for i in range(len(left.lbases)):
            self.lbases[i] = (left.lbases[i] + right.lbases[i]) % MOD

class SegmentTree:
    def __init__(self, n, arr):
        self.n = n
        # We need to precompute Fibonacci weights up to n
        self.fib_w = [0] * (n + 2)
        self.fib_w[0] = 0
        self.fib_w[1] = 1
        for i in range(2, n + 3):
            self.fib_w[i] = (self.fib_w[i-1] + self.fib_w[i-2]) % MOD

        self.tree = [Node(n + 2) for _ in range(4 * n)]
        self.build(arr)

    def build(self, arr):
        self._build(node=1, l=1, r=self.n, arr=arr)

    def _build(self, node, l, r, arr):
        if l == r:
            self.tree[node].val_sum = arr[l-1] % MOD
            return

        mid = (l + r) // 2
        self._build(2 * node, l, mid, arr)
        self._build(2 * node + 1, mid + 1, r, arr)
        self.tree[node].merge(self.tree[2 * node], self.tree[2 * node + 1])

    def push(self, node, l, r):
        if self.tree[node].add_lazy == 0:
            return
        mid = (l + r) // 2

        left_node = 2 * node
        right_node = 2 * node + 1
        lazy = self.tree[node].add_lazy

        # Left child
        self.tree[left_node].val_sum = (self.tree[left_node].val_sum + 
                                        lazy * (self.lsum(l, mid)) ) % MOD
        # Right child
        self.tree[right_node].val_sum = (self.tree[right_node].val_sum + 
                                         lazy * (self.lsum(mid + 1, r))) % MOD

        self.tree[left_node].add_lazy = (self.tree[left_node].add_lazy + lazy) % MOD
        self.tree[right_node].add_lazy = (self.tree[right_node].add_lazy + lazy) % MOD

        self.tree[node].add_lazy = 0

    def lsum(self, l, r):
        # Pre-compute prefix sums of fib_w
        return (self.fib_w[r+1] - self.fib_w[l-1] + MOD) % MOD

    def update_point(self, idx, value):
        self._update_point(1, 1, self.n, idx, value)

    def _update_point(self, node, l, r, idx, value):
        if l == r:
            diff = (value - self.tree[node].val_sum) % MOD
            self.tree[node].val_sum = value % MOD
            return

        mid = (l + r) // 2
        if idx <= mid:
            self._update_point(2 * node, l, mid, idx, value)
        else:
            self._update_point(2 * node + 1, mid + 1, r, idx, value)

        self.tree[node].merge(self.tree[2 * node], self.tree[2 * node + 1])

    def update_range(self, l, r, d):
        self._update_range(1, 1, self.n, l, r, d)

    def _update_range(self, node, l, r, ql, qr, d):
        if ql <= l and r <= qr:
            w = self.fib_w[r - l + 1]
            self.tree[node].val_sum = (self.tree[node].val_sum + 
                                       d * w) % MOD
            self.tree[node].add_lazy = (self.tree[node].add_lazy + d) % MOD
            return

        mid = (l + r) // 2
        if r <= ql or l > qr:
            return

        self._update_range(2 * node, l, mid, ql, qr, d)
        self._update_range(2 * node + 1, mid + 1, r, ql, qr, d)

        self.tree[node].merge(self.tree[2 * node], self.tree[2 * node + 1])

    def query(self, l, r):
        return self._query(1, 1, self.n, l, r)

    def _query(self, node, l, r, ql, qr):
        if ql <= l and r <= qr:
            return self.tree[node].val_sum

        mid = (l + r) // 2
        res = 0
        if l < ql:
            res = (res + self._query(2 * node, l, mid, ql, qr)) % MOD
        if l <= qr:
            res = (res + self._query(2 * node + 1, mid + 1, r, ql, qr)) % MOD
        return res

def parse_input(s):
    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))
    operations = []
