def solution(s):
    """
    Calculate the maximum number of chessmen that can be placed on an n x m chessboard
    where each pair of chessmen has Manhattan distance exactly 3.

    Args:
        s: A string containing two space-separated integers n and m

    Returns:
        A string containing the maximum number of chessmen
    """
    if not s.strip():
        return ""

    n, m = map(int, s.strip().split())
    total = n * m

    # If either dimension is <= 2, no valid pairs can be formed
    if min(n, m) <= 2:
        return "0"

    # For larger boards, we can place chessmen on all cells (if even)
    # or all but one cell (if odd)
    if total % 2 == 1:
        return str(total - 1)
    else:
        return str(total)


