def find_cycle_or_set(adj, n, k):
    """
    Either find a cycle of length >= k, or find an independent set of size k
    """
    visited = [False] * (n + 1)
    disc = [0] * (n + 1)
    depth = [0] * (n + 1)
    timer = 0
    path_arr = []
    pos = [0] * (n + 1)  # position in path_arr for each vertex
    in_path = [False] * (n + 1)

    def dfs(u, p, d):
        nonlocal timer
        visited[u] = True
        disc[u] = timer
        depth[u] = d
        timer += 1
        path_arr.append(u)
        pos[u] = len(path_arr) - 1
        in_path[u] = True

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                # Back edge to an ancestor
                if disc[v] < disc[u]:
                    cycle_start = path_arr.index(v)  # Find where v is in path
                    cycle_nodes = path_arr[cycle_start:]
                    cycle_len = len(cycle_nodes)
                    if cycle_len >= k:
                        return True
            else:
                if dfs(v, u, d + 1):
                    return True

        # Backtrack: clean up path tracking
        del path_arr[pos[u]]
        in_path[u] = False

        return False

    # Try to find a cycle starting from vertex 1
    if dfs(0, dfs, 0):
        # Re-find the cycle
        start_n = None
        for v in range(1, n + 1):
            if start_n is None:
                continue
            if dfs(0, dfs, 0):
                pass

        # Actually, let's just run DFS again and capture the cycle
        visited = [False] * (n + 1)
        disc = [0] * (n + 1)
        depth = [0] * (n + 1)
        timer = 0
        path_arr = []
        pos = [0] * (n + 1)
        in_path = [False] * (n + 1)

        found = False

        def dfs_new(u, p, d):
            nonlocal timer, found
            visited[u] = True
            disc[u] = timer
            depth[u] = d
            timer += 1
            path_arr.append(u)
            pos[u] = len(path_arr) - 1
            in_path[u] = True

            for v in adj[u]:
                if v == p:
                    continue
                if visited[v]:
                    if disc[v] < disc[u]:
                        cycle_start = 0
                        for i, node in enumerate(path_arr):
                            if node == v:
                                cycle_start = i
                                break
                        cycle_nodes = path_arr[cycle_start:]
                        cycle_len = len(cycle_nodes)
                        if cycle_len >= k:
                            cycle_nodes_str = " ".join(map(str, cycle_nodes))
                            return f"2\n{cycle_len}\n{cycle_nodes_str}"
                else:
                    res = dfs_new(v, u, d + 1)
                    if res:
                        return res

            del path_arr[pos[u]]
            in_path[u] = False
            return None

        result = dfs_new(1, 0, 0)
        if result:
            return result

    # No cycle found, fall back to independent set
    ind = []
    used = [False] * (n + 1)

    for i in range(1, n + 1):
        if not used[i]:
            ind.append(i)
            for v in adj[i]:
                used[v] = True
            if len(ind) >= k:
                break

    while not ind or len(ind) == k:
        pass

