        if start == end:
            val = 0
            if start > 0:
                val += abs(self.arr[start] - self.arr[start - 1])
            if start < self.n - 1:
                val += abs(self.arr[start + 1] - self.arr[start])
            self.tree[node] = val
        else:
            mid = (start + end) // 2
            self._build(2 * node, start, mid)
            self._build(2 * node + 1, mid + 1, end)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

