                if k < n - 1:
                    old_right = abs(st.arr[k + 1] - st.arr[k])
                    new_right = abs(st.arr[k + 1] - (st.arr[k] + x))
                    change2 = new_right - old_right
                else:
                    change2 = 0

                total = change1 + change2
                if total > best:
                    best = total
            anse.append(str(best))
        else:
            st.range_add(1, 0, n - 1, l, r, x)
            # Update tree root with sum
            st.tree[1] = sum(abs(st.arr[i] - st.arr[i-1]) for i in range(1, n))

    return '\n'.join(anse)

