from collections import deque

def solution(input_str):
    lines = [line.strip() for line in input_str.strip().split('\n')]
    if len(lines) < 2:
        return "0\n"

    lines = [l for l in lines if l]
    n, k = map(int, lines[0].split())
    prerequisites = list(map(int, lines[1].split()))

    # Read pairs
    pairs = []
    for i in range(2, min(len(lines), 2 + k)):
        parts = lines[i].split()
        if len(parts) >= 2:
            x, y = int(parts[0]), int(parts[1])
            pairs.append((x, y))

    # Build the prerequisite DAG
    adj = [[] for _ in range(n + 1)]
    in_degree = [0] * (n + 1)

    for i in range(1, n + 1):
        p = prerequisites[i - 1]
        if p != 0:
            adj[p].append(i)
            in_degree[i] += 1

    # Topological sort using Kahn's algorithm
    queue = deque([i for i in range(1, n + 1) if in_degree[i] == 0])
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check if all nodes are processed
    if len(result) != n:
        return "0\n"

    # Check if all special pairs are satisfied (consecutive in ordering)
    position = {node: i for i, node in enumerate(result)}

    for x, y in pairs:
        pos_x = position.get(x)
        pos_y = position.get(y)

        if pos_x is None or pos_y is None:
            return "0\n"

        if pos_y != pos_x + 1:
            return "0\n"

    return " ".join(map(str, result)) + "\n"

