def grundy(n, k):
    if n == 0:
        return 0

    moves = {grundy(n-1, k)}

    if n % 2 == 0:  # n is even
        if k % 2 == 0:
            # Even k: split produces XOR sum of 0
            moves.add(0)
        else:
            # Odd k: split produces XOR sum of grundy(n/2)
            moves.add(grundy(n // 2, k))

    return min(set(moves) - {x for x in range(len(moves))})

