def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    x, k, n, q = map(int, lines[0].split())
    costs = list(map(int, lines[1].split()))

    special = {}
    for i in range(2, q + 2):
        parts = lines[i].split()
        if len(parts) >= 2:
            p, wp = map(int, parts[:2])
            special[p] = wp

    start = tuple(range(1, x + 1))
    target = tuple(range(n - x + 1, n + 1))

    if x == 1 and n == 1:
        return "0\n"

    min_cost = {start: 0}
    pq = [(0, start)]

    while pq:
        cost, state = heapq.heappop(pq)

        if state == target:
            return str(cost) + "\n"

        if cost > min_cost.get(state, float('inf')):
            continue

        state_list = list(state)
        for i in range(x):
            for dist in range(1, k + 1):
                new_pos = state_list[i] + dist
                if new_pos > n:
                    break

                new_state = [s for s in state_list]
                new_state[i] = new_pos

                # Check if position is already occupied by another pollywog
                if new_pos in new_state:
                    continue

                new_state = tuple(sorted(new_state))

                add = costs[dist - 1]
                if new_pos in special:
                    add += special[new_pos]

                if new_state not in min_cost or cost + add < min_cost[new_state]:
                    min_cost[new_state] = cost + add
                    heapq.heappush(pq, (cost + add, new_state))

    return "0\n"

