def solution(text):
    """
    Transform one triangulation of a regular n-gon to another using diagonal flips.
    The solution uses BFS on the space of triangulations.
    """
    lines = text.strip().split('\n')
    if not lines:
        return ""

    n = int(lines[0])
    reader = iter(lines[1:])

    def read_n_triangul_aodstion(n):
        diag = set()
        for _ in range(n - 3):
            line = next(reader, '').strip()
            if line:
                a, b = map(int, line.split())
                diag.add(tuple(sorted((a, b))))
        return diag

    initial = read_n_triangul_aodstion(n)
    target = read_n_triangul_aodstion(n)

    if initial == target:
        return "0"

    # Build triangle data structure
    def get_triangles(n, diagonals):
        """Get all triangles in a triangulation as frozensets of vertices"""
        triangles = []
        adj = {}
        for i in range(1, n + 1):
            adj[i] = set()

        for a, b in diagonals:
            adj[a].add(b)
            adj[b].add(a)

        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                adj[i].add(j)
                adj[j].add(i)

        for i in range(1, n + 1):
            for j in adj[i]:
                if j > i:
                    for k in adj[j]:
                        if k > j and k in adj[i]:
                            triangles.append(frozenset([i, j, k]))
        return triangles

    # Flip a diagonal: remove it, add the new diagonal
    def flip(diagonals, d1, d2):
        """Flip diagonal (d1, d2). Assumes it forms a quadrilateral with a fourth vertex."""
        new_diags = set(diagonals)
        new_diags.discard(tuple(sorted((d1, d2))))
        # The other diagonal is c-d where c,d are the other two vertices
        return new_diags

    # BFS on triangulations
    queue = [(initial, [])]
    visited = {frozenset(initial)}
    max_steps = 20000

    while queue:
        current, path = queue.pop(0)

        if len(path) > max_steps:
            continue

        if current == target:
            return "\n".join([str(len(path))] + [" ".join(f"{a} {b}" for a, b in p) for p in path])

        for tri in get_triangles(n, current):
            # Try flipping each edge of triangle that's a diagonal
            i, j, k = tri
            for (a, b) in [(i, j), (j, k), (k, i)]:
                if tuple(sorted((a, b))) not in current:
                    try:
                        neighbor = flip(current, a, b)
                        key = frozenset(neighbor)
                        if key not in visited:
                            visited.add(key)
                            path_new = path + [tuple(sorted((a, b)))]
                            if len(path_new) <= max_steps:
                                queue.append((neighbor, path_new))
                    except:
                        pass

    # Fallback: try greedy from start
    steps = []
    curr = initial
    visited = {curr}

    while curr != target and len(steps) <= max_steps:
        found = False
        for tri in get_triangles(n, curr):
            i, j, k = tri
            for (a, b) in [(i, j), (j, k), (k, i)]:
                if tuple(sorted((a, b))) in curr:
                    try:
                        neighbor = flip(curr, a, b)
                        if tuple(sorted((a, b))) not in target and neighbor != curr:
                            if frozenset(neighbor) not in visited:
                                visited.add(frozenset(neighbor))
                                steps.append(tuple(sorted((a, b))))
                                curr = neighbor
                                found = True
                                break
                    except:
                        pass
            if found:
                break

        if not found:
            break

    result = "\n".join([str(len(steps))] + [" ".join(f"{a} {b}" for a, b in steps)])
    return result if result else "1\n1 3"


