def solution(input_str):
    parts = input_str.strip().split()
    if len(parts) != 2:
        return '0\n'
    l, r = int(parts[0]), int(parts[1])

    if l > r:
        return '0\n'

    # A number is lucky for Peter if it's prime
    # A number is lucky for Bob if it can be written as a^2 + b^2 (a, b >= 1)
    # For primes: 2 = 1^2 + 1^2, and primes p ≡ 1 (mod 4) can be written as sum of two squares
    # We need to count primes in [l, r] where p == 2 or p % 4 == 1

    # Handle edge case
    l = max(l, 2)

    # Sieve to find all primes up to sqrt(r)
    limit = int(r**0.5) + 2
    if limit < 2:
        limit = 2

    is_prime_small = [True] * (limit + 1)
    is_prime_small[0] = is_prime_small[1] = False
    for i in range(2, limit + 1):
        if is_prime_small[i]:
            for j in range(i*i, limit + 1, i):
                is_prime_small[j] = False

    primes = [i for i, p in enumerate(is_prime_small) if p]

    # Segmented sieve to count qualifying primes in [l, r]
    count = 0
    CHUNK_SIZE = 100000  # Balance between memory and efficiency
    start = l

    while start <= r:
        end = min(start + CHUNK_SIZE - 1, r)
        size = end - start + 1
        is_prime_chunk = [True] * size

        # Mark composites using small primes
        for p in primes:
            if p * p > end:
                break

            # Find first multiple of p >= start
            first = p * ((start + p - 1) // p)

            # Mark multiples of p
            # Starting from first - start position, but ensure we don't mark p itself
            mark_start = first - start
            if mark_start < 0:
                mark_start += p

            for j in range(mark_start, size, p):
                if j < size:
                    is_prime_chunk[j] = False

        # Count primes in this chunk that satisfy the condition (2 or ≡ 1 mod 4)
        for i, is_prime in enumerate(is_prime_chunk):
            if is_prime:
                val = start + i
                if val == 2 or val % 4 == 1:
                    count += 1

        start += CHUNK_SIZE

    return str(count) + '\n'


