    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    num_to_idx = {x: i for i, x in enumerate(p)}
    adj = [[] for _ in range(n)]

    # Build graph based on constraints
    # If x is in A, then a-x must also be in A
    # If x is in B, then b-x must also be in B
    for i in range(n):
        x = p[i]
        # A-complement edge
        if (a - x) in num_to_idx:
            j = num_to_idx[a - x]
            adj[i].append(j)
            adj[j].append(i)

        # B-complement edge
        if (b - x) in num_to_idx:
            j = num_to_idx[b - x]
            adj[i].append(j)
            adj[j].append(i)

    visited = [False] * n
    result = [0] * n

    for start in range(n):
        if visited[start]:
            continue

        # Find connected component using DFS
        component = []
        stack = [start]
        visited[start] = True

        while stack:
            node = stack.pop()
            component.append(node)
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)

        # Check if component can go to set A
        can_A = True
        for node in component:
            x = p[node]
            ac = a - x
            if ac in num_to_idx:
                # If complement exists, it must be in same component
                if num_to_idx[ac] not in component:
                    can_A = False
                    break

        if can_A:
            for i in component:
                result[i] = 0
        else:
            # Try to assign to set B
            can_B = True
            for node in component:
                x = p[node]
                bc = b - x
                if bc in num_to_idx:
                    # If complement exists, it must be in same component
                    if num_to_idx[bc] not in component:
                        can_B = False
                        break

            if can_B:
                for i in component:
                    result[i] = 1
            else:
                return "NO\n"

    return "YES\n" + " ".join(map(str, result)) + "\n"

