def count_and_sum_s(length, tight, x_digits=None):
    MOD = 10**9 + 7
    powers = [1] * (2 * length)
    for i in range(1, 2 * length):
        powers[i] = powers[i-1] * 10 % MOD

    if length == 1:
        if tight:
            limit = int(x_digits[0]) if x_digits else 9
        else:
            limit = 9
        return sum(d for d in range(1, limit + 1)) % MOD

    result_count = 0
    result_sum = 0

    memo = {}

    def dp(pos, tight, counts, s_sum):
        state = (pos, tuple(counts), tight)
        if state in memo:
            return memo[state]

        if pos == length:
            return 1, 0

        cnt = 0
        s_val = 0

        limit = int(x_digits[pos]) if tight and x_digits and pos < len(x_digits) else 9

        # Leading digit must be 1-9
        if pos == 0:
            for d in range(1, limit + 1):
                tight = tight and (d == limit)
                counts[d] = counts.get(d, 0) + 1
                cnt += 1
                s_val = (s_val + compute_sorted_value(counts.copy(), length) * powers[0]) % MOD
                memo[state] = (cnt, s_val)
            return memo[state]

        return dp(pos + 1, tight, counts, s_sum)

    return (result_sum, result_count)

