def get_all_paths(i, j, n, m, path=None):
    """Get all monotonous paths from (i,j) to (n-1,m-1)"""
    if path is None:
        path = []

    if i == n - 1 and j == m - 1:
        return [path + [(i, j)]]

    paths = []
    if i < n - 1:
        paths.extend(get_all_paths(i + 1, j, n, m, path + [(i, j)]))
    if j < m - 1:
        paths.extend(get_all_paths(i, j + 1, n, m, path + [(i, j)]))

    return paths

