        [(1, 0), (2, 0), (1, 1), (2, 1)],  # T pointing right
        [(0, 0), (1, 0), (1, 1), (2, 0)],  # T pointing left
    ]

    def is_valid(r, c, orientation):
        for dr, dc in orientation:
            rr, cc = r + dr, c + dc
            if not (0 <= rr < n and 0 <= cc < m):
                return False
            if grid[rr][cc] != '.':
                return False
        return True

    def place_piece(r, c, orientation, letter_idx, letters):
        for i, (dr, dc) in enumerate(orientation):
            grid[r + dr][c + dc] = letters[letter_idx]

    def remove_piece(r, c, orientation, letters):
        for dr, dc in orientation:
            grid[r + dr][c + dc] = '.'

    def backtrack(idx, placed_count):
        nonlocal max_pieces, best_grid
        if placed_count >= max_pieces:
            max_pieces = placed_count
            best_grid = [row[:] for row in grid]
            return

        # If we've gone through all cells
        if idx >= n * m:
            return

        r, c = idx // m, idx % m

        # Try placing a piece starting at this cell
        if all(grid[r][c] == '.' for _ in range(m)):
            for orientation in orientations:
                if is_valid(r, c, orientation):
                    place_piece(r, c, orientation, len(letters), letters)
                    backtrack(idx + m, placed_count + 1)
                    remove_piece(r, c, orientation, letters)

        # Try moving to next cell
        backtrack(idx + 1, placed_count)

    max_pieces = 0
    best_grid = []
    letters = [None] * 26  # Up to 26 letters

    backtrack(0, 0)

    return f"{max_pieces}\n" + "\n".join("".join(row) for row in best_grid)

