        # ans[i] = direction of lantern i='L' means directed left, 'R' means directed right
        ans = [''] * n
        # illuminated[i] = True if lantern i is illuminated by some other lantern
        illuminated = [False] * n

        possible = True

        # Process from left to right
        i = 0
        while i < n and possible:
            # Lantern i needs to be illuminated
            # Check left neighbors first
            j = min(i + 1, max(1, i + 1))
            k = 0
            # Try to find a lantern that can illuminate i
            for candidate in range(max(1, i - 1), -1, -1):
                if candidate >= 0 and ans[candidate] == '' and not illuminated[candidate]:
                    # This candidate can illuminate i if left direction works
                    if i > candidate and (candidate - i) <= ans[candidate]:
                        if candidate - i <= p[candidate]:
                            ans[candidate] = 'R'
                            k = True
                            break

            if not k:
                # Check right neighbors
                for j in range(i + 1, min(i + p[i] + 1, n)):
                    if ans[j] == '' and not illuminated[j]:
                        illuminate_candidate(j, i, p)

        # Second pass: ensure all are illuminated
        for i in range(n):
            if not illuminated[i]:
                # Try to find any lantern that can illuminate i
                found = False
                # Check left direction (some lantern j > i with p_j can illuminate i)
                for j in range(i + 1, n):
                    if (j - i) <= p[j] and not illuminated[j]:
                        illuminater, direction = candidate_illuminator(j, i, p, j)
                        if illuminater != -1:
                            ans[illuminater] = direction
                            illuminate(illuminater, i, ans, illuminated)
                            found = True
                            break

                if not found:
                    possible = False
                    break

        if not possible:
            ans = [''] * n
            results.append('NO')
        else:
            # Verify all are illuminated
            for i in range(n):
                if not illuminated[i]:
                    possible = False
                    break

            if possible:
                direction_str = ''.join(ans)
                results.append('YES\n' + direction_str)
            else:
                results.append('NO')

    return '\n'.join(results)


