    n = int(s.strip())
    if n == 0:
        return "0\n"

    visited = {n}
    queue = deque([(n, 0)])
    digits_cache = {}

    while queue:
        current, ops = queue.popleft()

        if current == 0:
            return str(ops) + "\n"

        s_current = str(current)
        digits = {int(d) for d in s_current}

        for digit in digits:
            new_val = current - digit
            if new_val not in visited:
                visited.add(new_val)
                queue.append((new_val, ops + 1))

